(() => {
  const url=new URL(location.href),page=url.searchParams.get('page'),main=document.querySelector('#main');
  if(url.searchParams.has('article'))return;
  const rooms=[{id:'exhibits',n:'01',name:'造物陈列室',en:'OBJECT STUDIES',desc:'看看器物如何制成，又怎样被使用和保存。',image:'cover-magic-oil.webp'},{id:'travel',n:'02',name:'五大陆旅行案头',en:'A JOURNEY IN NOTES',desc:'选一处目的地，准备行程和行装。',image:'nautical-chart.png'},{id:'street',n:'03',name:'城市切片',en:'A STREET THROUGH THE DAY',desc:'走进普诺伊瓦的一条街，看看清晨、午后和入夜时的街景。',image:'cover-daily-oil.webp'}];
  const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const para=ps=>ps.map(p=>`<p>${e(p)}</p>`).join('');
  const article=id=>window.CURTAIN_CONTENT.articles.find(a=>a.id===id);
  const readings=ids=>`<div class="field-readings"><span class="field-label">沿着馆藏继续读</span>${ids.map(id=>{const a=article(id);return a?`<a href="?article=${e(id)}">${e(a.title)} <b aria-hidden="true">↗</b></a>`:'';}).join('')}</div>`;
  const choices=(items,key,selected)=>items.map(i=>`<button type="button" data-${key}="${e(i.id)}" aria-pressed="${i.id===selected}">${e(i.name)}</button>`).join('');
  const keep=(key,val)=>{url.searchParams.set(key,val);history.replaceState(null,'',url);};
  const select=(items,key,fallback)=>items.find(i=>i.id===url.searchParams.get(key))?.id||fallback;
  const landing=`<section class="field-entrances" id="fieldrooms"><div class="section-heading"><div><p>研究所 · 开放展室</p><h2>走进开放展室</h2></div></div><div class="field-room-grid">${rooms.map(r=>`<a href="?page=${r.id}" class="field-room"><img src="assets/${r.image}" alt="" loading="lazy"><div><span class="field-label">${r.n} / ${r.en}</span><h3>${r.name}<b aria-hidden="true">↗</b></h3><p>${r.desc}</p></div></a>`).join('')}</div></section>`;
  if(!page){main.querySelector('.desk-feature')?.insertAdjacentHTML('beforebegin',landing);return;}
  if(page==='library'){main.querySelector('.catalog-heading')?.insertAdjacentHTML('beforebegin',landing);return;}
  const room=rooms.find(r=>r.id===page);if(!room)return;
  document.title=room.name+' | 帷幕研究所';document.body.dataset.surface='fieldroom';document.body.dataset.collection=page;
  document.querySelectorAll('#nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.getAttribute('href')==='?page=exhibits')a.setAttribute('aria-current','page');});
  main.innerHTML=`<header class="field-masthead"><div><a class="back" href="./#fieldrooms">← 研究所首页</a><p class="field-label">FIELD NOTES / ${room.en}</p><h1>${room.name}</h1><p class="field-intro">${room.desc}</p></div><span class="field-seal" aria-hidden="true">${room.n}<small>帷幕研究所</small></span></header><nav class="field-nav" aria-label="开放展室">${rooms.map(r=>`<a href="?page=${r.id}" ${r.id===page?'aria-current="page"':''}>${r.name}</a>`).join('')}</nav><div class="field-body" id="field-workspace"></div>`;
  const root=main.querySelector('#field-workspace');
  if(page==='exhibits'){
    const items=window.CURTAIN_EXHIBITS;let id=select(items,'object',items[0].id),view='use',releaseModel=()=>{};
    root.innerHTML=`<div class="field-section-heading"><div><span class="field-label">六件样本 / 器物与材料</span><h2>器物与材料</h2></div><p>选一件展品，翻开它的档案。</p></div><div class="specimen-list" role="group" aria-label="选择展品">${choices(items,'object',id)}</div><div class="exhibit-grid"><div class="specimen-board"><div class="specimen-image"></div><div class="specimen-caption"><span></span><span>形制示意 · 研究所绘录</span></div><div class="specimen-facts"></div></div><article class="specimen-reading"><div id="specimen-detail"></div><div class="field-tabs" role="group" aria-label="档案阅读方式"><button type="button" data-view="use" aria-pressed="true">使用札记</button><button type="button" data-view="record" aria-pressed="false">材料与流转</button></div><div id="specimen-pages" aria-live="polite"></div></article></div><p class="field-editor-note">日用灯为据造物性质拟写的生活样本。器物形制由研究所绘录。</p>`;
    const render=()=>{const a=items.find(i=>i.id===id);root.querySelectorAll('[data-object]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.object===id)));releaseModel();releaseModel=window.CurtainSpecimens.mount(root.querySelector('.specimen-image'),a.shape);root.querySelector('.specimen-caption span').textContent='样本 '+a.number+' / '+a.tag;root.querySelector('.specimen-facts').innerHTML=`<dl>${a.facts.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>`;root.querySelector('#specimen-detail').innerHTML=`<span class="field-label">${e(a.kind)} / ${a.number}</span><h2>${e(a.name)}</h2><p class="field-lead">${e(a.lead)}</p>`;renderPages();};
    const renderPages=()=>{const a=items.find(i=>i.id===id),cs=view==='use'?[a.chapters[0]]:[a.chapters[1],{title:'展品记录',paragraphs:[`资料：${a.sources.join(' · ')}。`]}];root.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));root.querySelector('#specimen-pages').innerHTML=cs.map(c=>`<section><h3>${e(c.title)}</h3>${para(c.paragraphs)}</section>`).join('')+readings(a.links);};
    root.querySelectorAll('[data-object]').forEach(b=>b.addEventListener('click',()=>{id=b.dataset.object;keep('object',id);render();}));root.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;renderPages();}));render();
  }
  if(page==='travel'){
    const data=window.CURTAIN_TRAVEL,cs=data.continents,ps=data.purposes;let from=select(cs,'from',cs[0].id),to=select(cs,'to',cs[3].id),purpose=select(ps,'purpose',ps[0].id),mode=select(Object.entries(data.transport).map(([id,v])=>({id})), 'mode','surface');
    root.innerHTML=`<div class="travel-layout"><form class="travel-form"><span class="field-label">JOURNEY / 整理一次出发</span><h2>你想去哪里？</h2><label for="travel-from">出发大陆</label><select id="travel-from">${cs.map(c=>`<option value="${c.id}" ${c.id===from?'selected':''}>${c.name}</option>`).join('')}</select><label for="travel-to">目的大陆</label><select id="travel-to">${cs.map(c=>`<option value="${c.id}" ${c.id===to?'selected':''}>${c.name}</option>`).join('')}</select><label for="travel-purpose">这趟出行</label><select id="travel-purpose">${ps.map(c=>`<option value="${c.id}" ${c.id===purpose?'selected':''}>${c.name}</option>`).join('')}</select><fieldset><legend>交通打算</legend>${Object.entries(data.transport).map(([id,v])=>`<label class="travel-radio"><input type="radio" name="transport" value="${id}" ${id===mode?'checked':''}>${e(v.name)}</label>`).join('')}</fieldset><button type="button" class="field-copy">抄下行装单 ↓</button><p class="travel-status" role="status"></p></form><article class="travel-notebook" id="travel-notebook" aria-live="polite"></article></div>`;
    let pack=[];root.querySelector('.travel-form').addEventListener('submit',ev=>ev.preventDefault());
    const render=()=>{const a=cs.find(c=>c.id===from),b=cs.find(c=>c.id===to),p=ps.find(c=>c.id===purpose),m=data.transport[mode];pack=[...new Set([...b.packing,...p.packing])];root.querySelector('#travel-notebook').innerHTML=`<div class="journey-route"><span>${e(a.name)}</span><b aria-hidden="true">${from===to?'↻':'⟶'}</b><span>${e(b.name)}</span></div><p class="field-label">${e(p.name)} / ${e(m.name)}</p><h2>${from===to?'在大陆上出行':'前往另一片大陆'}</h2><p class="field-lead">${from===to?'这次行程留在同一片大陆。城内、近郊和乡镇之间的路程各有长短。':(mode==='gate'?'从住处到界门、从界门到落脚的城市，都需要另作安排。':(mode==='gate'?'从住处到界门、从界门到落脚的城市，都需要另作安排。':'跨海出行需要分段安排，先到交通节点，再考虑后续路程。'))}</p><section><h3>抵达 · ${e(b.position)}</h3><p class="travel-climate">${e(b.climate)}</p>${para(b.arrival)}</section><section><h3>出行准备</h3>${para(p.paragraphs)}</section><section><h3>${from===to&&mode==='surface'?'城内与大陆上的道路':e(m.name)}</h3>${para(from===to&&mode==='surface'?[m.paragraphs[0],'城镇之间路程有长有短。记下陆上接驳、途中可能需要的食宿和返程安排，到当地后逐项商量。']:m.paragraphs)}${from!==to&&mode==='surface'?'<p>先写下希望前往的港口，再向当地了解船只与接驳的实际安排。</p>':''}</section><section><h3>到当地以后</h3>${para(b.manners)}${para(Array.isArray(b.trade)?b.trade:[b.trade])}</section><section><h3>行装清单</h3><ul class="packing-list">${pack.map((x,i)=>`<li><label><input type="checkbox" data-pack="${i}"><span>${e(x)}</span></label></li>`).join('')}</ul><p class="packing-progress" role="status">已收好 0 / ${pack.length} 件</p></section><section><h3>预计开销</h3><ul class="travel-costs">${m.costs.map(c=>`<li>${e(c)}</li>`).join('')}</ul><p class="field-editor-note">开销按项目整理。交通与住宿的数额随行程另记。</p></section>${readings([b.article,'daily-journey','gates'])}`;root.querySelectorAll('[data-pack]').forEach(x=>x.addEventListener('change',()=>{root.querySelector('.packing-progress').textContent=`已收好 ${root.querySelectorAll('[data-pack]:checked').length} / ${pack.length} 件`;}));root.querySelector('.travel-status').textContent='';};
    [['travel-from','from',v=>from=v],['travel-to','to',v=>to=v],['travel-purpose','purpose',v=>purpose=v]].forEach(([id,key,set])=>root.querySelector('#'+id).addEventListener('change',ev=>{set(ev.target.value);keep(key,ev.target.value);render();}));root.querySelectorAll('[name="transport"]').forEach(x=>x.addEventListener('change',()=>{mode=x.value;keep('mode',mode);render();}));root.querySelector('.field-copy').addEventListener('click',()=>{const b=cs.find(c=>c.id===to),text=`帷幕研究所 · 行装单\n${cs.find(c=>c.id===from).name} → ${b.name}\n${ps.find(c=>c.id===purpose).name} / ${data.transport[mode].name}\n\n${pack.map(x=>'□ '+x).join('\n')}`,blob=new Blob([text],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='帷幕行装单.txt';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);root.querySelector('.travel-status').textContent='行装单已整理为文本，可保存带走。';});render();
  }
  if(page==='street'){
    const d=window.CURTAIN_STREET,times=[{id:'morning',name:'清晨'},{id:'noon',name:'午后'},{id:'evening',name:'入夜'}];let place=select(d.places,'place',d.places[0].id),time=select(times,'time','morning');
    root.innerHTML=`<div class="field-section-heading"><div><span class="field-label">PRUNOIVA / 街巷观察</span><h2>${e(d.title)}</h2></div><p>${e(d.intro)}</p></div><div class="street-times" role="group" aria-label="街上的时段">${choices(times,'time',time)}</div><div class="street-layout"><div class="street-map" data-time="${time}"><div class="street-scene-wrap"><div class="street-map-title"><span>普诺伊瓦</span><small>城市切片 / 街巷绘录</small></div><img class="street-scene" src="assets/street/prunoiva-morning.png" alt="普诺伊瓦街巷鸟瞰插画，六处店铺和公共建筑沿石板街分布" width="1122" height="1402" fetchpriority="high">${d.places.map((p,i)=>`<button class="street-pin" type="button" data-place="${p.id}" style="--x:${i%2?75:25}%;--y:${[23,23,49,49,77,77][i]}%" aria-label="${e(p.name)}" aria-pressed="${p.id===place}"><span>${String(i+1).padStart(2,'0')}</span><b>${e(p.name)}</b></button>`).join('')}</div><div class="street-map-footer"><span>普诺伊瓦 · 街巷手记</span><small>点选编号，沿街走走</small></div><div class="street-directory" role="group" aria-label="沿街地点">${d.places.map((p,i)=>`<button type="button" data-place="${p.id}" aria-pressed="${p.id===place}"><span>${String(i+1).padStart(2,'0')}</span>${e(p.name)}<b>↗</b></button>`).join('')}</div></div><article id="street-reading" class="street-reading" aria-live="polite"></article></div><p class="field-editor-note">${e(d.note)}</p>`;
    const render=()=>{const p=d.places.find(p=>p.id===place),s=p.scenes[time];root.querySelectorAll('[data-time]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.time===time));});root.querySelectorAll('[data-place]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.place===place)));root.querySelector('.street-map').dataset.time=time;root.querySelector('.street-scene').src='assets/street/prunoiva-'+time+'.png';root.querySelector('.street-scene').alt=times.find(t=>t.id===time).name+'的普诺伊瓦街巷插画';root.querySelector('#street-reading').innerHTML=`<span class="field-label">${e(times.find(t=>t.id===time).name)} / ${e(p.kind)}</span><h2>${e(p.name)}</h2><p class="field-lead">${e(p.lead)}</p><h3>${e(s.title)}</h3>${para(s.paragraphs)}<details class="street-sources"><summary>这处观察的资料</summary><p>${p.sources.map(e).join(' · ')}</p></details>${readings(p.links)}<div class="street-next"><button type="button" class="field-next">沿街再走一家 →</button></div>`;root.querySelector('.field-next').addEventListener('click',()=>{place=d.places[(d.places.findIndex(p=>p.id===place)+1)%d.places.length].id;keep('place',place);render();});};root.querySelectorAll('button[data-time]').forEach(b=>b.addEventListener('click',()=>{time=b.dataset.time;keep('time',time);render();}));root.querySelectorAll('[data-place]').forEach(b=>b.addEventListener('click',()=>{place=b.dataset.place;keep('place',place);render();if(window.innerWidth<=720)root.querySelector('#street-reading').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}));render();
  }
})();
